	if err != nil {
		fmt.Println(err)
		return
	}
	defer file.Close()

	// Create a CSV reader
	reader := csv.NewReader(file)

	// Read the header
	header, err := reader.Read()
	if err != nil {
		fmt.Println(err)
		return
	}

	// Parse the header to find the index of each column
	indexName := -1
	indexBirthday := -1
	indexDied := -1
	indexFather := -1
	indexMother := -1
	indexBrother := -1
	indexSister := -1

	for i, col := range header {
		switch strings.TrimSpace(col) {
		case "Name":
			indexName = i
		case "Birthday":
			indexBirthday = i
		case "Died":
			indexDied = i
		case "Father":
			indexFather = i
		case "Mother":
			indexMother = i
		case "Brother":
			indexBrother = i
		case "Sister":
			indexSister = i
		}
	}

	if indexName == -1 || indexBirthday == -1 || (indexDied != -1 && indexFather == -1) {
		fmt.Println("CSV header is missing required columns.")
		return
	}

	// Read the data rows
	var people []Person

	for {
		row, err := reader.Read()
		if err != nil {
			break
		}

		firstName := strings.TrimSpace(row[indexName])
		birthdayStr := strings.TrimSpace(row[indexBirthday])

