			}
		}

		motherFirstName := ""
		motherLastName := ""
		if indexMother != -1 {
			motherFullName := strings.TrimSpace(row[indexMother])
			parts := strings.SplitN(motherFullName, " ", 2)
			motherFirstName = parts[0]
			if len(parts) > 1 {
				motherLastName = parts[1]
			}
		}

		brotherFirstName := ""
