		if indexBrother != -1 && row[indexBrother] != "" {
			brotherFullName := strings.TrimSpace(row[indexBrother])
			parts := strings.SplitN(brotherFullName, " ", 2)
			brotherFirstName = parts[0]
			if len(parts) > 1 {
				brotherLastName = parts[1]
			}
