				{Sister, sisterLastName, "Sister"},
			},
		}

		// Add the person to the list
		people = append(people, person)
	}

	// Print the JSON array to stdout
	jsonData, err := json.MarshalIndent(people, "", "  ")
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println(string(jsonData))
}
